class HybridVectorSearch:
    def __init__(self, dense_index, sparse_index):
        self.dense = dense_index
        self.sparse = sparse_index

    # Reciprocal Rank Fusion (RRF) combines dense vector and BM25 rankings
    def search(self, query_vec, query_text, k: int = 10, rrf_k: int = 60):
        dense_hits = self.dense.search(query_vec, efSearch=64, top_k=50)
        sparse_hits = self.sparse.search(query_text, top_k=50)
        scores = {}
        for rank, hit in enumerate(dense_hits):
            scores[hit.id] = scores.get(hit.id, 0.0) + 1.0 / (rrf_k + rank + 1)
        for rank, hit in enumerate(sparse_hits):
            scores[hit.id] = scores.get(hit.id, 0.0) + 1.0 / (rrf_k + rank + 1)
        return sorted(scores.items(), key=lambda x: x[1], reverse=True)[:k]
